import { z } from 'zod';

/** QR payload generated by the desktop (Settings → Remote Access). */
const pairingQrSchema = z.object({
  ip: z.string().min(1),
  port: z.number().int().positive(),
  token: z.string().min(1),
});

export type PairingTarget = z.infer<typeof pairingQrSchema>;

/** Parses the raw QR content. Returns null when it is not a Lumen pairing code. */
export function parsePairingQr(data: string): PairingTarget | null {
  let raw: unknown;
  try {
    raw = JSON.parse(data);
  } catch {
    return null;
  }
  const parsed = pairingQrSchema.safeParse(raw);
  return parsed.success ? parsed.data : null;
}
